"The ticked ones, or with none ticked the whole trash: deleted for good, with everything made from them. Asks first.": "Os marcados, ou sem nenhum marcado a lixeira inteira: excluídos de vez, com tudo o que foi feito a partir deles. Pergunta antes.",
