"To the trash": "Para a lixeira",
"The Librarian lives in Forge's lab, which does not answer: not found": "O Bibliotecário vive no laboratório do Forge, que não responde: não encontrado",
"a LoRA for YuE2 from your own songs · the guide: LORA-TRAINING.md": "uma LoRA para o YuE2 a partir das suas próprias canções · o guia: LORA-TRAINING.md",
