"≈ A guess: the painter does not know this instrument, and the critic did not find it in any of the pictures it drew.": "≈ Um palpite: o pintor não conhece este instrumento, e o crítico não o achou em nenhuma das imagens que ele desenhou.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten. Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "⚠ Um nome no estilo é um pedido, não uma promessa. O que ▶ A e ▶ B tocam é o que o YuE2 dá para ele, umas nove vezes em dez. Algumas provas são excelentes, A e B concordam, e ainda assim o instrumento não é o pedido: confie no ouvido, não no nome.",
