"Waveform Free 14 or newer: free, no track or export limits; it opens the studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 ou mais recente: grátis, sem limite de faixas ou de exportação; abre o DAWproject do estúdio (File > Import Other > Import a DAWproject file). O Waveform 13 não é suportado",
