"The current official decoder, and the default. The cleanest, best-sounding one: start here.": "O decodificador oficial atual, e o padrão. O mais limpo, o de melhor som: comece por ele.",
"The older official decoder. The published benchmark scores were made with it. Less clean than Standard; some hear it as more musical. Same encoder, only the decoder differs.": "O decodificador oficial antigo. As notas de benchmark publicadas foram feitas com ele. Menos limpo que o Standard; alguns o ouvem como mais musical. Mesmo codificador, só o decodificador muda.",
"A community weight mix of the two official decoders: 2/3 Standard + 1/3 Legacy. Not newly trained. It sits between the clean Standard and the more musical Legacy; the real-audio LoRA's authors suggest it.": "Uma mistura comunitária dos pesos dos dois decodificadores oficiais: 2/3 Standard + 1/3 Legacy. Não foi retreinado. Fica entre o Standard limpo e o Legacy mais musical; os autores do LoRA de áudio real o sugerem.",
