"{#0} Unicode arrows (→): write -> instead": "{#0} setas Unicode (→): escreva -> no lugar",
"dynamics marks (never in the official styles)": "marcas de dinâmica (nunca nos estilos oficiais)",
"{#0} \"Label:\" fields (5 of 110 official styles use any)": "{#0} campos \"Label:\" (5 dos 110 estilos oficiais usam algum)",
"{#0} bracket line in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "{#0} linha entre colchetes na letra com um \"Label:\", uma seta ou uma marca p/f (nenhuma nos exemplos oficiais)",
"{#0} bracket lines in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "{#0} linhas entre colchetes na letra com um \"Label:\", uma seta ou uma marca p/f (nenhuma nos exemplos oficiais)",
"{#0} instruments": {"one": "{#0} instrumento", "other": "{#0} instrumentos"},
"{#0} heard": "ouvidos: {#0}",
"{#0} questioned": "questionados: {#0}",
"{#0} not identified": "não identificados: {#0}",
"{#0} not judged yet": "ainda não julgados: {#0}",
"the Librarian does not answer: no probes to play": "o Bibliotecário não responde: nenhuma sonda para tocar",
"{#0} styles": {"one": "{#0} estilo", "other": "{#0} estilos"},
"{#0} style": {"one": "{#0} estilo", "other": "{#0} estilos"},
"what a probe gave instead of its instrument": "o que uma sonda deu no lugar do seu instrumento",
"Nothing matches.": "Nada corresponde.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ Um nome no estilo é um pedido, não uma promessa. O que ▶ A e ▶ B tocam é o que o YuE2 dá para ele, cerca de nove vezes em dez.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "Algumas sondas são excelentes, e A e B concordam, mas o instrumento não é o pedido: confie no ouvido, não no nome.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "O que se pediu ao YuE2 para tocar, um instrumento ou um estilo por vez, em sondas de dois minutos (um minuto nas primeiras), duas sementes cada, A e B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Um instrumento molda o estilo da peça inteira: nomear um também move o arranjo. Um chiado ou um farfalhar de papel, como num disco gasto, é uma semente azarada: faça de novo com outra.",
