"Its takes stay as they are: they are heard and read, never changed, moved or thrown away, and they leave All Workspaces and the search (a take also in a workspace that is not frozen stays there). The workspace greys out; Unfreeze in its ⋯ menu brings everything back.": "Os takes ficam como estão: são ouvidos e lidos, nunca mudados, movidos ou jogados fora, e saem de Todos os espaços e da busca (um take também num espaço não congelado fica lá). O espaço fica cinza; Descongelar no menu ⋯ dele traz tudo de volta.",
