"Loading the Sound Heresy": "Carregando a Heresia Sonora",
"Artwork for “{0}” already waits in the queue for a card": "A arte de “{0}” já espera na fila por uma placa",
"Artwork for “{0}” is being drawn already": "A arte de “{0}” já está sendo desenhada",
"Artwork for “{0}” waits in the queue for a card with room; it starts by itself (Engine → GPUs says which card does what)": "A arte de “{0}” espera na fila por uma placa com espaço; começa sozinha (Motor → GPUs diz qual placa faz o quê)",
"Artwork for “{0}” waits in the queue: {1}. It starts by itself when a card has room": "A arte de “{0}” espera na fila: {1}. Começa sozinha quando uma placa tiver espaço",
