"The prompt's column: drag to widen; ← → from the keyboard; Home or a double click for its own width": "A coluna do prompt: arraste para alargar; ← → pelo teclado; Home ou clique duplo para a largura própria",
"The library's column: drag to widen; ← → from the keyboard; Home or a double click for its own width": "A coluna da biblioteca: arraste para alargar; ← → pelo teclado; Home ou clique duplo para a largura própria",
"To the stage": "Para o palco",
"All of it to the form": "Tudo para o formulário",
"Its painter, fine-tune, sampling and adapters as well, with its seed and shape: Draw paints this picture again": "O pintor, o fine-tune, a amostragem e os adaptadores também, com a semente e o formato: Desenhar pinta esta imagem de novo",
