"pictures for your songs from a prompt of your own: square, wide and tall from one seed, painted by Krea 2 Muse or Qwen-Image": "imagens para suas canções a partir de um prompt seu: quadradas, largas e altas de uma semente, pintadas pelo Krea 2 Muse ou pelo Qwen-Image",
