"its limit {0} GB": "o limite dela {0} GB",
"the studio's": "a do estúdio",
"the backbone {0}": "o backbone {0}",
"compute {0} has no BF16 tensor cores: BF16 runs slower than Q8_0 here": "a computação {0} não tem núcleos tensoriais BF16: aqui BF16 roda mais devagar que Q8_0",
"{0} is not on this machine: Engine → Models and LoRAs fetches it": "{0} não está nesta máquina: Motor → Modelos e LoRAs o baixa",
"context {0} rows": "contexto {0} linhas",
"context {0}": "contexto {0}",
"the whole context": "o contexto inteiro",
"VAE tiles {0}": "blocos do VAE {0}",
"Auto for {0} GB": "Auto para {0} GB",
