"The whole model; on a card older than Ampere (an RTX 20xx, a Quadro RTX) it runs without its tensor cores, slower than Q8_0": "O modelo inteiro; numa placa mais antiga que Ampere (uma RTX 20xx, uma Quadro RTX) ele roda sem os núcleos tensoriais, mais devagar que Q8_0",
"Style listener": "Ouvinte de estilo",
