"{#0} GB of VRAM when it listens: a 24 GB card": "{#0} GB de VRAM quando ouve: uma placa de 24 GB",
"the Artist's painter: Krea 2 Muse by Stable Yogi with Krea 2's text encoder and VAE, the content filter its licence asks for, and the prompt writer (Qwen3-4B)": "o pintor do Pintor: Krea 2 Muse by Stable Yogi com o codificador de texto e o VAE do Krea 2, o filtro de conteúdo que a licença pede, e o redator de prompts (Qwen3-4B)",
"the Artist's painter (no card here has the 16 GB Krea 2 wants): SDXL CyberRealistic, and the prompt writer (Qwen3-4B)": "o pintor do Pintor (nenhuma placa aqui tem os 16 GB que o Krea 2 quer): SDXL CyberRealistic, e o redator de prompts (Qwen3-4B)",
