"the Artist's Qwen-Image painters": "os pintores Qwen-Image do Pintor",
"for a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "para uma placa de 16 GB (abaixo de 20 GB o codificador de texto lê o prompt no processador: 17 GB de RAM); meio minuto por imagem numa 3090; menos quando parte dele já está aqui",
"For a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "Para uma placa de 16 GB (abaixo de 20 GB o codificador de texto lê o prompt no processador: 17 GB de RAM); meio minuto por imagem numa 3090; menos quando parte dele já está aqui",
"For a card of 24 GB; less when some of it is here": "Para uma placa de 24 GB; menos quando parte dele já está aqui",
"Under Qwen's research licence: research and evaluation only, not for commercial use (a cover for a song that is sold is commercial use); a card of 24 GB, about two minutes a picture": "Sob a licença de pesquisa da Qwen: só pesquisa e avaliação, não para uso comercial (uma capa para uma canção vendida é uso comercial); uma placa de 24 GB, cerca de dois minutos por imagem",
"LoRA trainer's base": "Base do treinador LoRA",
