"A folder that is there already; {0} goes into it as «{1}». On the same disk it is renamed at once; on another it is copied, checked file by file, then the link is switched, and the old copy stays, renamed, for you to remove after a look.": "Uma pasta que já existe; {0} entra nela como «{1}». No mesmo disco é renomeado na hora; em outro é copiado, conferido arquivo por arquivo, depois o vínculo é trocado, e a cópia antiga fica, renomeada, para você remover depois de uma olhada.",
