"The lines' numbers in the box, as a code editor shows them (Alt+K marks a line, Alt+J goes to the next mark)": "Os números das linhas na caixa, como um editor de código os mostra (Alt+K marca uma linha, Alt+J vai à próxima marca)",
"Marks: {0}": "Marcas: {0}",
"Marked lines: Alt+K marks the cursor's line or unmarks it, Alt+J goes to the next, Alt+Shift+J to the one before, Alt+Shift+K clears them. Press to go to the next one.": "Linhas marcadas: Alt+K marca a linha do cursor ou a desmarca, Alt+J vai à próxima, Alt+Shift+J à anterior, Alt+Shift+K as limpa. Aperte para ir à próxima.",
"Press to go to the next one.": "Aperte para ir à próxima.",
"line {0}: {1}": "linha {0}: {1}",
"Tags not closed or astray: {0}": "Tags não fechadas ou perdidas: {0}",
"Round brackets to look at: {0}": "Parênteses para olhar: {0}",
"Stress marks off a vowel: {0}": "Acentos tônicos fora de uma vogal: {0}",
"Words with two stress marks: {0}": "Palavras com dois acentos tônicos: {0}",
"A stress mark (U+0301) stands right after the vowel it stresses. Press to go to the next one.": "Um acento tônico (U+0301) fica logo depois da vogal que acentua. Aperte para ir ao próximo.",
"One word, two stress marks: meant, or a slip? Press to go to the next one.": "Uma palavra, dois acentos tônicos: de propósito, ou um deslize? Aperte para ir ao próximo.",
"{0} is a spacing accent, not the stress mark (U+0301 after the vowel)": "{0} é um acento com espaçamento, não o acento tônico (U+0301 depois da vogal)",
