"Beats no vowel carries, counted with the syllables in each line's bar (drawn lighter): a word with no vowel (с, в, к, з, й, ў) and a stop closed against an affricate inside a word (глу-п-цо́в)": "Tempos que nenhuma vogal carrega, contados com as sílabas na barra de cada linha (desenhados mais claros): uma palavra sem vogal (с, в, к, з, й, ў) e uma oclusiva fechada contra uma africada dentro de uma palavra (глу-п-цо́в)",
"The lyrics editor's keys, as in mcedit:\nAlt+K  mark the cursor's line (again: unmark it)\nAlt+J  the next mark · Alt+Shift+J the one before\nAlt+O  clear the marks (Alt+Shift+K too)\nAlt+L  go to a line by its number\nCtrl+Y  delete the line\nAlt+↑ Alt+↓  move the line, or the lines selected\n[ at a line's start, or Ctrl+Space  the section tags\nCtrl+F  find in the box\nAlt+I  the instruments' and styles' cheat-sheet\nCtrl+Z  take a change back": "As teclas do editor de letras, como no mcedit:\nAlt+K  marcar a linha do cursor (de novo: desmarcar)\nAlt+J  a próxima marca · Alt+Shift+J a anterior\nAlt+O  limpar as marcas (Alt+Shift+K também)\nAlt+L  ir a uma linha pelo número\nCtrl+Y  apagar a linha\nAlt+↑ Alt+↓  mover a linha, ou as linhas selecionadas\n[ no início da linha, ou Ctrl+Espaço  as tags de seção\nCtrl+F  buscar na caixa\nAlt+I  a cola de instrumentos e estilos\nCtrl+Z  desfazer uma mudança",
"Already in the lyrics, line {0}: a song has one": "Já está na letra, linha {0}: uma canção tem uma",
"The lyrics number their verses: this is the next one": "A letra numera as estrofes: esta é a próxima",
"{0} times in the 110 official examples": "{0} vezes nos 110 exemplos oficiais",
