"already at line {0}": "já na linha {0}",
"the next verse": "a próxima estrofe",
"↑ ↓ choose · Enter or Tab puts it in · Esc closes": "↑ ↓ escolher · Enter ou Tab insere · Esc fecha",
"TEST: none of the 110 official examples writes it, so YuE2 may sing it as words or pass it by. Listen before you keep it.": "TESTE: nenhum dos 110 exemplos oficiais o escreve, então o YuE2 pode cantá-lo como palavras ou pulá-lo. Ouça antes de manter.",
