"Render this take's sound again with this VAE: it was made before takes kept their latents, so it takes as long as its sound did\n{0}": "Renderizar de novo o som deste take com este VAE: ele foi feito antes de os takes guardarem seus latentes, então leva o mesmo tempo que o som levou\n{0}",
"Decode this take again with this VAE: its own sound, another decoder, in seconds\n{0}": "Decodificar de novo este take com este VAE: o próprio som, outro decodificador, em segundos\n{0}",
