"This version\n{0}": "Esta versão\n{0}",
"Sound seed {#0}\nsame music, another grain": "Semente do som {#0}\na mesma música, outro grão",
"None on this server. Start it with --sliders to add voice and genre sliders.": "Nenhum neste servidor. Inicie com --sliders para adicionar sliders de voz e gênero.",
"{#0} decoders · {1} picked in the ☰ menu · a finished song can add another from its page": "{#0} decodificadores · {1} escolhido no menu ☰ · uma canção pronta pode adicionar outro na sua página",
