"Between the sections a vocalise an octave up, written into the lyrics as «(Ooh, aah)», instead of a bar's rest": "Entre as seções um vocalise uma oitava acima, escrito na letra como «(Ooh, aah)», em vez de um compasso de pausa",
"The take in hand out of the studio: the mixed track as it is, or the whole take into your DAW (with its stems, once they are split here)": "O take em mãos fora do estúdio: a faixa mixada como está, ou o take inteiro na sua DAW (com os stems, depois de separados aqui)",
