"End at…": "Terminar em…",
"End the take at a moment: its last 2 s fade out, and nothing after it is kept. For a song that runs on past its proper end (in Full, the score's leftover bars after the last words). The moment is where the player stands when this take plays; otherwise you are asked. From the take's kept latents in seconds (the very sound), else its music codes rendered again. A new take; this one stays.": "Terminar o take num momento: seus últimos 2 s somem em fade, e nada depois é guardado. Para uma canção que continua além do fim certo (no Completo, os compassos que sobram da partitura depois das últimas palavras). O momento é onde o player está quando este take toca; senão, você é perguntado. A partir dos latentes guardados do take em segundos (o próprio som), senão seus códigos musicais renderizados de novo. Um take novo; este fica.",
"Fade in…": "Fade de entrada…",
"Fade the take in: its first seconds rise from silence (2 s unless you say otherwise), for a song that starts too abruptly. From the take's kept latents in seconds (the very sound), else its music codes rendered again. A new take; this one stays.": "Fade de entrada no take: os primeiros segundos sobem do silêncio (2 s, a não ser que diga outro valor), para uma canção que começa abrupta demais. A partir dos latentes guardados do take em segundos (o próprio som), senão seus códigos musicais renderizados de novo. Um take novo; este fica.",
"Loop…": "Loop…",
"A loop from this take: 1, 2, 4 or 8 bars on its score's bar lines, from the bar where the player stands (else the first), seamless (its end runs into its start), saved as a WAV named with its tempo and key": "Um loop a partir deste take: 1, 2, 4 ou 8 compassos nas barras de compasso da partitura, do compasso onde o player está (senão o primeiro), sem emenda (o fim corre para o início), salvo como WAV com o andamento e o tom no nome",
"On 15 s": "Avançar 15 s",
"Back 15 s": "Voltar 15 s",
"On to the next quarter-minute mark. The → key: to the next 5 s mark": "Até a próxima marca de quarto de minuto. A tecla →: até a próxima marca de 5 s",
"A sound when a run ends": "Um som quando uma execução termina",
"A sound when a run made here ends: two notes up when it is done (a queue of runs once, when its last one ends), two down when one fails. None over a new song that starts playing by itself; as loud as the player. Click to make none.": "Um som quando uma execução feita aqui termina: duas notas subindo quando está pronta (uma fila de execuções uma vez só, quando a última termina), duas descendo quando uma falha. Nenhum por cima de uma canção nova que começa a tocar sozinha; tão alto quanto o player. Clique para não ter nenhum.",
"Count again": "Contar de novo",
"Count the folders' files and sizes again": "Contar de novo os arquivos e tamanhos das pastas",
"Scan the machine": "Escanear a máquina",
"What this machine has, and what suits it: the backbone, the context and the VAE tiles, the painter": "O que esta máquina tem, e o que combina com ela: o backbone, o contexto e os blocos do VAE, o pintor",
"Check again": "Verificar de novo",
"Compare what is here with the pinned lists again; nothing is downloaded": "Comparar de novo o que há aqui com as listas fixadas; nada é baixado",
"Restart the engine": "Reiniciar o motor",
"The engine reads its backbones, decoders and sliders when it starts": "O motor lê seus backbones, decodificadores e sliders ao iniciar",
"Folders": "Pastas",
"What the studio downloads beside itself: the decoders and the sliders, Whisper, the stems' models, UniverSR and the LoRAs, which the install brings, and the extras you ask for. Each file comes from Hugging Face at the revision the release pins and is checked against its size; a download cut short goes on where it stopped. Nothing is downloaded until you press Fetch.": "O que o estúdio baixa ao lado de si: os decodificadores e os sliders, o Whisper, os modelos dos stems, o UniverSR e as LoRAs, que a instalação traz, e os extras que você pedir. Cada arquivo vem do Hugging Face na revisão que a versão fixa e é conferido pelo tamanho; um download interrompido continua de onde parou. Nada é baixado até você apertar Baixar.",
"Where your work lives: the songs (with the workspaces fetched from Hugging Face), the trash, the Artist's pictures and the Writer's documents. Each may live on any disk: the studio's folder then holds a link to it, and everything reads it there as before. The models, the LoRAs and the training sets keep their places.": "Onde seu trabalho mora: as canções (com os espaços baixados do Hugging Face), a lixeira, as imagens do Pintor e os documentos do Escritor. Cada um pode morar em qualquer disco: a pasta do estúdio então guarda um vínculo para ele, e tudo o lê ali como antes. Os modelos, as LoRAs e os conjuntos de treino ficam onde estão.",
