"Make a song in Full plan or Melody only mode first; Direct mode keeps no score.": "Faça antes uma canção no modo Plano completo ou Só melodia; o modo Direto não guarda partitura.",
"A reference is a PNG, JPEG or WebP picture": "Uma referência é uma imagem PNG, JPEG ou WebP",
"The picture could not be read": "A imagem não pôde ser lida",
"Pick a take on the right first": "Escolha antes um take à direita",
"The prompt its artwork was drawn from": "O prompt de onde a arte dele foi desenhada",
"A prompt from its title and style: say more of what you see": "Um prompt a partir do título e do estilo: diga mais do que você vê",
"Put the take's prompt in place of the one written here?": "Pôr o prompt do take no lugar do que está escrito aqui?",
"What is written now goes; each run below keeps its own prompt.": "O que está escrito agora sai; cada execução abaixo guarda o próprio prompt.",
