"The painters, the Qwen fine-tunes and the adapters the studio can fetch for the Artist, each with its size, here or not: from the studio's models repository and from their makers": "Os pintores, os fine-tunes Qwen e os adaptadores que o estúdio pode baixar para o Pintor, cada um com seu tamanho, aqui ou não: do repositório de modelos do estúdio e dos seus autores",
"Painters and adapters to fetch": "Pintores e adaptadores para baixar",
