"Qwen fine-tunes": "Fine-tunes Qwen",
"Artist's adapters": "Adaptadores do Pintor",
"the fp8 fine-tunes of Qwen-Image 2512 for finished realism (a card of 24 GB), from {0}, shared there by their authors' leave (Civitai: share and sell)": "os fine-tunes fp8 do Qwen-Image 2512 para realismo acabado (uma placa de 24 GB), de {0}, compartilhados lá com a permissão dos autores (Civitai: compartilhar e vender)",
"adapters for the Artist's painters, from {0}, shared there by their authors' leave (Civitai: share and sell): Cinematic Movie Still, Cinematic Dark Lighting and Lenovo UltraReal for Krea 2; Lenovo UltraReal and Frank Frazetta for Qwen-Image 2.1; Film Photography and Photostyle by Sean Archer for 2512": "adaptadores para os pintores do Pintor, de {0}, compartilhados lá com a permissão dos autores (Civitai: compartilhar e vender): Cinematic Movie Still, Cinematic Dark Lighting e Lenovo UltraReal para o Krea 2; Lenovo UltraReal e Frank Frazetta para o Qwen-Image 2.1; Film Photography e Photostyle by Sean Archer para o 2512",
"and Qwen-Image 2512's parts (17.7 GB) when they are not here": "e as partes do Qwen-Image 2512 (17,7 GB) quando não estão aqui",
"seven adapters": "sete adaptadores",
"the qwen fine-tunes {0}": "os fine-tunes qwen {0}",
"the artist's adapters {0}": "os adaptadores do pintor {0}",
"Keep the canvas and draw the shapes picked in the form (Ctrl+Enter)": "Manter a tela e desenhar os formatos escolhidos no formulário (Ctrl+Enter)",
