"Eight adapters at most in the list: take one off first": "Oito adaptadores no máximo na lista: tire um antes",
"Four in the run at most: this one came in muted (right-click: mute another and bring it in)": "Quatro no máximo na execução: este entrou mudo (clique direito: deixe outro mudo e traga este)",
"Four in the run at most: mute one first": "Quatro no máximo na execução: deixe um mudo antes",
"Take it off the list": "Tirá-lo da lista",
