"Info…": "Info…",
"Its trigger words into the prompt": "As palavras-gatilho dele no prompt",
"Copy its trigger words": "Copiar as palavras-gatilho dele",
"Trigger words go into the prompt by themselves": "As palavras-gatilho entram no prompt sozinhas",
"Look it up on Civitai": "Procurá-lo no Civitai",
"Its page on Civitai": "A página dele no Civitai",
"Copy its file's name": "Copiar o nome do arquivo dele",
"To the art's trash…": "Para a lixeira das artes…",
"What it is made for, its trigger words, its file and what its trainer wrote into it": "Para que ele foi feito, as palavras-gatilho, o arquivo e o que o treinador escreveu nele",
"When an adapter comes into the run its trigger words are added to the prompt, and taken out when it leaves": "Quando um adaptador entra na execução, as palavras-gatilho dele são acrescentadas ao prompt, e tiradas quando ele sai",
"Its SHA-256 alone goes to civitai.com: its name, base model and trigger words come back": "Só o SHA-256 dele vai para civitai.com: voltam o nome, o modelo base e as palavras-gatilho",
"With the files beside it; the Librarian's Trash (Art) gives it back": "Com os arquivos ao lado dele; a Lixeira (Arte) do Bibliotecário o devolve",
"Known to Civitai: {0}": "Conhecido no Civitai: {0}",
"In the art's trash: {0} (the Librarian's Trash (Art) gives it back)": "Na lixeira das artes: {0} (a Lixeira (Arte) do Bibliotecário o devolve)",
"Not moved: {0}": "Não movido: {0}",
"Move {0} to the art's trash, with the files beside it (its picture, its notes)? The Librarian's Trash (Art) gives it back.": "Mover {0} para a lixeira das artes, com os arquivos ao lado dele (a imagem, as notas)? A Lixeira (Arte) do Bibliotecário o devolve.",
