"civitai.com → Account settings → API Keys": "civitai.com → Account settings → API Keys",
"Many adapters come without a key; some ask for one. The key goes from this page to the studio's lab and from there to civitai.com alone, never into a file.": "Muitos adaptadores vêm sem chave; alguns pedem uma. A chave vai desta página ao laboratório do estúdio e de lá só para civitai.com, nunca para um arquivo.",
