"Made for {0}: it goes into the folder of {1}.": "Feito para {0}: vai para a pasta de {1}.",
"Made for {0}: no painter here is known to take it, so it may reach none of the layers of {1}.": "Feito para {0}: nenhum pintor aqui é conhecido por aceitá-lo, então pode não alcançar nenhuma camada de {1}.",
