"this is a {0} on Civitai, not an adapter (LORA, LoCon, DoRA)": "isto é um {0} no Civitai, não um adaptador (LORA, LoCon, DoRA)",
"the file came, but its SHA-256 is not the one Civitai gives for it: thrown away": "o arquivo chegou, mas o SHA-256 dele não é o que o Civitai informa: descartado",
"the file came, but it is not a safetensors adapter: thrown away": "o arquivo chegou, mas não é um adaptador safetensors: descartado",
"Civitai sent a page, not the file: this adapter wants your API key (civitai.com → Account settings → API Keys)": "O Civitai mandou uma página, não o arquivo: este adaptador quer a sua chave de API (civitai.com → Account settings → API Keys)",
"a fetch from Civitai is under way ({0}): one at a time": "um download do Civitai está em andamento ({0}): um de cada vez",
