"this studio runs under Pinokio: update it there, by Update in Pinokio's menu": "este estúdio roda sob o Pinokio: atualize-o lá, pelo Update no menu do Pinokio",
"this machine has no systemd-run for the update to run in: update by hand (git fetch --tags, git checkout the release, ./build.sh)": "esta máquina não tem systemd-run para rodar a atualização: atualize à mão (git fetch --tags, git checkout da versão, ./build.sh)",
"TTA: each tile through the upscaler in its eight orientations (four turns, each mirrored), averaged: steadier edges and textures, up to eight times the time (Upscayl's way)": "TTA: cada bloco passa pelo ampliador nas oito orientações (quatro giros, cada um espelhado), com média: bordas e texturas mais estáveis, até oito vezes o tempo (o jeito do Upscayl)",
"Upscale them all, in one run: 2K or 4K by the upscaler chosen, or the passes kept": "Ampliar todas, numa execução: 2K ou 4K pelo ampliador escolhido, ou as passagens guardadas",
"2K · {0}": "2K · {0}",
"4K · {0}": "4K · {0}",
