"the size of {0} is not known": "o tamanho de {0} não é conhecido",
"too large: {0} would be {#1} px on the long side, {#2} is the most": "grande demais: {0} teria {#1} px no lado maior, {#2} é o máximo",
"{0} is {#1}×{#2} already: {3} is {#4} px on its long side": "{0} já tem {#1}×{#2}: {3} tem {#4} px no lado maior",
"too large: {0} at ×{#1}, {#2} px is the most on the long side": "grande demais: {0} a ×{#1}, {#2} px é o máximo no lado maior",
"no such picture in the run: {0}": "não há essa imagem na execução: {0}",
"Its strength over the steps: keyframes of a multiplier at a share of the steps, as ComfyUI's LoRA hooks. «0%:1, 50%:1, 60%:0» keeps it whole for half the steps and lets it go by 60 %; «0%:0, 30%:1» brings it in after the start. Between keyframes the multiplier runs straight; two at one share make a step.": "A força ao longo dos passos: quadros-chave de um multiplicador numa fração dos passos, como os hooks de LoRA do ComfyUI. «0%:1, 50%:1, 60%:0» o mantém inteiro na metade dos passos e o solta até 60 %; «0%:0, 30%:1» o faz entrar depois do início. Entre quadros-chave o multiplicador segue em linha reta; dois na mesma fração fazem um degrau.",
"Its strength over the steps": "A força ao longo dos passos",
"Its keyframes": "Os quadros-chave dele",
"Not a keyframe: «{0}». Keyframes as «0%:1, 50%:1, 60%:0»: a share of the steps and a multiplier from 0 to 2, eight at most": "Não é um quadro-chave: «{0}». Quadros-chave como «0%:1, 50%:1, 60%:0»: uma fração dos passos e um multiplicador de 0 a 2, oito no máximo",
"an adapter's keyframes: one to {#0}, each a share of the steps and a multiplier": "os quadros-chave de um adaptador: de um a {#0}, cada um uma fração dos passos e um multiplicador",
