"Unload model: {0} GB in the card’s memory now (busy: it waits), and the Artist’s painter kept between runs on GPU {1}": "Descarregar o modelo: {0} GB na memória da placa agora (ocupado: ele espera), e o pintor do Pintor mantido entre execuções na GPU {1}",
