"Spectrum over the wave": "Espectro sobre a onda",
"Spectrum over the wave: the pointer on the wave brings the whole take's spectrogram up over the player, as wide as the wave, the section's words above it. Click to turn it off.": "Espectro sobre a onda: o ponteiro na onda traz o espectrograma do take inteiro sobre o player, tão largo quanto a onda, com a letra da seção acima. Clique para desligar.",
"The take's spectrum": "O espectro do take",
"spectral centroid": "centroide espectral",
"The spectral centroid: where the sound's weight sits at each moment, its brightness; higher is brighter": "O centroide espectral: onde fica o peso do som a cada momento, o brilho dele; mais alto é mais brilhante",
"RMS: how loud each moment is, in dBFS, in the lane at the foot; the dashed line is the take's own average": "RMS: o volume de cada momento, em dBFS, na faixa de baixo; a linha tracejada é a média do próprio take",
"Frequency scale": "Escala de frequências",
"The frequencies on a log scale, as the ear hears them: each octave as tall as the next": "As frequências numa escala logarítmica, como o ouvido as ouve: cada oitava da mesma altura que a seguinte",
"The frequencies on a linear scale: the highs wide, the lows packed at the foot": "As frequências numa escala linear: os agudos largos, os graves espremidos embaixo",
"The mean power of each band over the whole take (Welch, dB): SUB 20–80 Hz, LOW 80–300, MID 300–2k, HI-MID 2–6k, HIGH 6–12k, AIR 12–20k": "A potência média de cada banda no take inteiro (Welch, dB): SUB 20–80 Hz, LOW 80–300, MID 300–2k, HI-MID 2–6k, HIGH 6–12k, AIR 12–20k",
