"its painter said nothing for {#0} s: stopped": "o pintor não disse nada por {#0} s: parado",
"A second pass, as Viktor's ComfyUI workflow makes it: the picture brought up 1.5 or 2 times and painted over by its own painter, adapters, prompt and seed, with the form's steps and sampler; a run of its own": "Uma segunda passada, como o workflow do ComfyUI do Viktor faz: a imagem ampliada 1.5 ou 2 vezes e repintada pelo seu próprio pintor, adaptadores, prompt e semente, com os passos e o amostrador do formulário; uma execução própria",
"Second pass…": "Segunda passada…",
"How much the second pass may change the picture: 0.3 keeps its drawing and adds detail, 0.5 sharpens its matter, 0.7 repaints its forms": "Quanto a segunda passada pode mudar a imagem: 0.3 guarda o desenho e acrescenta detalhe, 0.5 apura a matéria, 0.7 repinta as formas",
"Second pass asked:": "Segunda passada pedida:",
"The second pass ×{0} waits for a card with room, then paints the picture over": "A segunda passada ×{0} espera uma placa com espaço, depois repinta a imagem",
"No second pass: {0}": "Sem segunda passada: {0}",
"second pass ×{0}": "segunda passada ×{0}",
"Extra noise": "Ruído extra",
"Fresh noise added to the picture before it is painted from, as Viktor's ComfyUI workflow does (InjectLatentNoise): 0 none, 0.3 new grain and detail, 0.6 his second pass, above 1 the picture's forms begin to break": "Ruído novo somado à imagem antes de pintar a partir dela, como faz o workflow do ComfyUI do Viktor (InjectLatentNoise): 0 nenhum, 0.3 grão e detalhe novos, 0.6 a segunda passada dele, acima de 1 as formas da imagem começam a se desfazer",
"extra noise {0}": "ruído extra {0}",
"Regions": "Regiões",
"Up to three parts of the frame, each with words of its own: at every step the painter is asked once more for each region, with the prompt and the region's words, and the answers are blended by soft-edged boxes (Latent Couple's way). Each region costs a whole pass more a step. Krea 2 and Qwen-Image 2512": "Até três partes do quadro, cada uma com suas próprias palavras: a cada passo o pintor é consultado mais uma vez para cada região, com o prompt e as palavras da região, e as respostas se misturam por caixas de borda suave (ao modo do Latent Couple). Cada região custa uma passada inteira a mais por passo. Krea 2 e Qwen-Image 2512",
"Add a region": "Adicionar uma região",
"Not with Qwen-Image 2.1: it edits by words": "Não com o Qwen-Image 2.1: ele edita por palavras",
"Where in the frame": "Onde no quadro",
"What is there": "O que há ali",
"Remove the region": "Remover a região",
"Left half": "Metade esquerda",
"Right half": "Metade direita",
"Top half": "Metade de cima",
"Bottom half": "Metade de baixo",
